// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        (bool ok1,) = address(c).call{value: 1 ether}("");
        vm.deal(address(0x2), 1 ether);
        vm.prank(address(0x2));
        (bool ok2,) = address(c).call{value: 1 ether}("");
        vm.deal(address(0x2), 4 ether);
        vm.prank(address(0x2));
        bool ok3;
        try c.multiplicate{value: 4 ether}(address(0x2)) {
            ok3 = true;
        } catch {
            ok3 = false;
        }
        assertTrue(ok3);
    }
}
